mapper.select:
SELECT  FROM quiz_attempt
WHERE quiz_id = #{quizId}
AND user_id = #{userId}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE quiz_attempt SET
    status = #{status}, close_reason = #{closeReason}, receipt_id = #{receiptId},
    submitted_at = #{submittedAt}, auto_score = #{autoScore}, manual_score = #{manualScore},
    total_score = #{totalScore}, manual_grading_complete = #{manualGradingComplete},
    version = version + 1, updated_at = #{updatedAt}
WHERE id = #{id}
